begin
 if jsonb_array_length(changes) <> 85 then raise exception 'Cantidad inesperada'; end if;
 if exists(select 1 from jsonb_to_recordset(changes) as x(id uuid,title text,expected_price numeric,expected_updated_at timestamptz,new_price numeric,ml_reference numeric,ml_url text,purchase_ars numeric) left join public.products p on p.id=x.id where p.id is null or p.is_active is distinct from true or p.retail_price is distinct from x.expected_price or p.updated_at is distinct from x.expected_updated_at) then raise exception 'El catálogo cambió; volver a auditar'; end if;
 if exists(select 1 from jsonb_to_recordset(changes) as x(id uuid,title text,expected_price numeric,expected_updated_at timestamptz,new_price numeric,ml_reference numeric,ml_url text,purchase_ars numeric) where new_price <= purchase_ars or new_price > ml_reference * 0.90) then raise exception 'Precio fuera de política'; end if;
 update public.products p set retail_price=x.new_price,updated_at=now() from jsonb_to_recordset(changes) as x(id uuid,title text,expected_price numeric,expected_updated_at timestamptz,new_price numeric,ml_reference numeric,ml_url text,purchase_ars numeric) where p.id=x.id;
 get diagnostics updated_count = row_count;
 if updated_count <> 85 then raise exception 'Cantidad actualizada inesperada'; end if;
end $pricing$;
commit;
select json_build_object('products',(select json_agg(p order by p.title) from public.products p),'costs',(select json_agg(c order by c.product_id) from public.product_costs c),'categories',(select json_agg(c) from public.categories c)) as snapshot;
